{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "The Glitch in the Grind",
      "goal": "Survive the initial Void-breach during a routine tutorial dungeon.",
      "chapter_role": "hook",
      "stakes_shift": "From a predictable level-grind to an existential system collapse where death is permanent.",
      "bridge": {
        "from_prev": "N/A - Start of Book",
        "to_next": "Kaelen escapes the collapsing dungeon with a corrupted UI and a unique 'Void-Touched' status."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 2,
      "title": "Error 404: Reality Not Found",
      "goal": "Identify the unique properties and exploits of the new Void-Touched class.",
      "chapter_role": "setup",
      "stakes_shift": "From a confused survivor to the possessor of a dangerous, system-breaking exploit.",
      "bridge": {
        "from_prev": "Kaelen is safe but his character sheet is a mess of purple text and errors.",
        "to_next": "The realization that the Void isn't just a glitch, but a resource he can harvest."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 3,
      "title": "The Tutorial is Over",
      "goal": "Escape the instanced starter zone before the System's 'Clean-Up' protocol deletes it.",
      "chapter_role": "pressure",
      "stakes_shift": "From exploring a new power to a desperate race against literal deletion.",
      "bridge": {
        "from_prev": "Kaelen masters his first Void skill just as the sky begins to pixelate and dissolve.",
        "to_next": "Kaelen breaks through the instance barrier into the wider, equally chaotic world."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 9
      }
    },
    {
      "chapter_id": 4,
      "title": "Welcome to the New Normal",
      "goal": "Reach the hub city of Oakhaven and assess the scale of the global System failure.",
      "chapter_role": "investigation",
      "stakes_shift": "From an isolated incident to the realization that the entire world's physics are failing.",
      "bridge": {
        "from_prev": "Kaelen arrives at the city gates to find the guards fighting invisible, 'null' entities.",
        "to_next": "Kaelen discovers that other 'glitched' players are being hunted by the System's automated enforcers."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 11
      }
    },
    {
      "chapter_id": 5,
      "title": "The Black Market of Mana",
      "goal": "Acquire a Void-stabilizer from the city's underworld to prevent his own mana-implosion.",
      "chapter_role": "journey",
      "stakes_shift": "From having an unstable power to possessing a controlled, illegal weapon.",
      "bridge": {
        "from_prev": "Kaelen's Void levels become critical, threatening to turn him into a Rift.",
        "to_next": "With his power stabilized, Kaelen learns of a 'Void Shard' hidden in a nearby high-level zone."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 6,
      "title": "Deep Dive into the Dark",
      "goal": "Clear the Sunken Crypt to retrieve the first Void Shard and upgrade his core stats.",
      "chapter_role": "trial",
      "stakes_shift": "From a local anomaly to a significant threat to the System's remaining balance.",
      "bridge": {
        "from_prev": "Kaelen enters the crypt, realizing the monsters inside have evolved using the Void.",
        "to_next": "Kaelen absorbs the Shard, triggering a global System announcement that names him a 'Primary Threat'."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 7,
      "title": "The Architect's Lie",
      "goal": "Decode the hidden developer logs within the Shard to find the truth about the Void.",
      "chapter_role": "revelation",
      "stakes_shift": "From a loyal System user to a rebel who knows the System was designed to fail.",
      "bridge": {
        "from_prev": "The Shard reveals that the 'Void' is actually the original state of the world.",
        "to_next": "Kaelen realizes he needs an ally who understands the old world's code."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "slow_burn",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 8,
      "title": "Two Wrongs Make a Right",
      "goal": "Form an uneasy alliance with Lyra, an exiled Sentinel who was framed by the System.",
      "chapter_role": "alliance",
      "stakes_shift": "From a solo survivor to the leader of a burgeoning fringe movement.",
      "bridge": {
        "from_prev": "Kaelen saves Lyra from a System 'Purge' squad.",
        "to_next": "Lyra agrees to lead Kaelen to the Rift Core, but only if they save her village first."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 9,
      "title": "The First Surge",
      "goal": "Defend Oakhaven from a massive Void-surge that threatens to overwrite the city.",
      "chapter_role": "siege",
      "stakes_shift": "From personal survival to becoming the reluctant protector of thousands of innocents.",
      "bridge": {
        "from_prev": "The sky turns purple as the first true Void-storm hits the city walls.",
        "to_next": "The city is saved, but the System marks Kaelen for immediate 'Hard Deletion'."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 11
      }
    },
    {
      "chapter_id": 10,
      "title": "The Purge Protocol",
      "goal": "Evade and defeat the 'Anti-Virus' enforcers sent to scrub Kaelen from the world.",
      "chapter_role": "confrontation",
      "stakes_shift": "From being a hunted anomaly to actively hunting the System's own agents.",
      "bridge": {
        "from_prev": "The System deploys a Level 99 'Inquisitor' to handle the glitch.",
        "to_next": "Kaelen uses a Void-exploit to defeat the Inquisitor, gaining administrative access."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 9
      }
    },
    {
      "chapter_id": 11,
      "title": "Awakening the Void",
      "goal": "Reach the core of the Rift and decide whether to patch the world or let it burn.",
      "chapter_role": "climax",
      "stakes_shift": "From a fugitive to the potential master of a new, unscripted world order.",
      "bridge": {
        "from_prev": "Kaelen and Lyra fight their way to the center of the world's source code.",
        "to_next": "Kaelen shatters the final System constraint, fully awakening the Void."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "steady",
        "expected_scene_count": 13
      }
    },
    {
      "chapter_id": 12,
      "title": "Patch Notes for the Apocalypse",
      "goal": "Establish a new base of operations and prepare for the inevitable System reboot attempt.",
      "chapter_role": "aftermath",
      "stakes_shift": "From ending the immediate threat to beginning a long-term revolution against the Architects.",
      "bridge": {
        "from_prev": "The old System is dead; the world is now a lawless, Void-infused sandbox.",
        "to_next": "Kaelen looks at his new UI: 'Quest Started: Rebuild Reality'."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "slow_burn",
        "expected_scene_count": 9
      }
    }
  ]
}
